     1→//! Project automation tasks
     2→//!
     3→//! All commands default to debug builds and verbose output.
     4→//! Use `-r` for release builds, `-q` for quiet output.
     5→//!
     6→//! # Usage
     7→//!
     8→//! ```text
     9→//! cargo xtask build                 # build all crates
    10→//! cargo xtask build ex-x1 -r        # build specific crate (release)
    11→//! cargo xtask build ex-x2 -opt -r   # build ex-x2 with nightly optimizations
    12→//!
    13→//! cargo xtask run hw-x1             # run specific crate (shows exit code)
    14→//! cargo xtask run .                 # run crate in current directory
    15→//!
    16→//! cargo xtask test                  # test all crates
    17→//! cargo xtask test ex-x1 -q         # test specific crate (quiet)
    18→//! cargo xtask test rlibc-x2         # includes rlibc-x2-tests binaries
    19→//! ```
    20→//!
    21→//! # Available Commands
    22→//!
    23→//! - `build` - Build crates (one at a time)
    24→//! - `run` - Build and run crates (shows exit code)
    25→//! - `test` - Run tests (with summary)
    26→//!
    27→//! # Optimized Builds (-opt flag)
    28→//!
    29→//! The `-opt` or `--optimized` flag enables nightly optimizations for x2 crates:
    30→//! - Nightly Rust toolchain
    31→//! - `-Z build-std=std,core,panic_abort` (rebuild std from source)
    32→//! - `-Z panic-immediate-abort` (minimal panic handling)
    33→//! - Custom target `x86_64-unknown-linux-rlibcx2.json`
    34→//!
    35→//! This produces significantly smaller binaries (~6KB stripped vs ~40KB).
    36→
    37→use std::fs;
    38→use std::io::Write;
    39→use std::path::Path;
    40→use std::process::{Command, ExitCode, Stdio};
    41→
    42→enum Subcommand {
    43→    Build,
    44→    Run,
    45→    Test,
    46→}
    47→
    48→struct Config {
    49→    subcommand: Subcommand,
    50→    quiet: bool,
    51→    fail_fast: bool,
    52→    debug: bool,
    53→    optimized: bool, // Use nightly + build-std + panic-immediate-abort for x2 crates
    54→    strip: bool,   // Strip debug symbols from binaries after building
    55→    crates: Vec<String>, // Empty means all crates
    56→}
    57→
    58→struct TestResult {
    59→    name: String,
    60→    passed: bool,
    61→    #[allow(dead_code)] // Captured for potential future use (e.g., detailed failure reports)
    62→    output: String,
    63→}
    64→
    65→fn main() -> ExitCode {
    66→    let config = parse_args();
    67→
    68→    // Get workspace root (xtask is at workspace root level)
    69→    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
    70→        .parent()
    71→        .expect("Could not find workspace root");
    72→
    73→    let cmd_name = match config.subcommand {
    74→        Subcommand::Build => "build",
    75→        Subcommand::Run => "run",
    76→        Subcommand::Test => "test",
    77→    };
    78→
    79→    // Get list of crates to operate on
    80→    let crates = if config.crates.is_empty() {
    81→        get_all_crates(workspace_root)
    82→    } else {
    83→        config.crates.clone()
    84→    };
    85→
    86→    // Run command on each crate
    87→    let mut results = Vec::new();
    88→    for crate_name in &crates {
    89→        // Skip lib-only crates for run command
    90→        if cmd_name == "run" && !crate_has_binary(crate_name, workspace_root) {
    91→            continue;
    92→        }
    93→
    94→        let result = run_cargo_on_crate(cmd_name, crate_name, workspace_root, &config);
    95→        let failed = !result.passed;
    96→        results.push(result);
    97→        if failed && config.fail_fast {
    98→            break;
    99→        }
   100→    }
   101→
   102→    // For test, also run rlibc-x2-tests if rlibc-x2 was included
   103→    if matches!(config.subcommand, Subcommand::Test) {
   104→        let should_run_rlibc_x2_tests = if config.crates.is_empty() {
   105→            true // Running all tests
   106→        } else {
   107→            config.crates.iter().any(|c| c == "rlibc-x2")
   108→        };
   109→
   110→        if should_run_rlibc_x2_tests {
   111→            let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, &config);
   112→            for result in rlibc_x2_results {
   113→                let failed = !result.passed;
   114→                results.push(result);
   115→                if failed && config.fail_fast {
   116→                    break;
   117→                }
   118→            }
   119→        }
   120→    }
   121→
   122→    // Only show summary for test command
   123→    if matches!(config.subcommand, Subcommand::Test) {
   124→        print_summary(&results)
   125→    } else {
   126→        // For build/run, just return success/failure based on results
   127→        if results.iter().any(|r| !r.passed) {
   128→            ExitCode::from(1)
   129→        } else {
   130→            ExitCode::SUCCESS
   131→        }
   132→    }
   133→}
   134→
   135→/// Get list of all crates in the workspace (excludes xtask and test crates)
   136→fn get_all_crates(workspace_root: &Path) -> Vec<String> {
   137→    // These are the crates we want to build/run/test
   138→    let crates = [
   139→        "ex-x1",
   140→        "ex-x2",
   141→        "ex-glibc",
   142→        "ex-musl",
   143→        "hw-x1",
   144→        "hw-x2",
   145→        "hw-glibc",
   146→        "hw-musl",
   147→        "rlibc-x1",
   148→        "rlibc-x2",
   149→        "is-libc-used",
   150→    ];
   151→
   152→    // Filter to crates that exist
   153→    crates
   154→        .iter()
   155→        .filter(|name| {
   156→            get_crate_path(name, workspace_root)
   157→                .join("Cargo.toml")
   158→                .exists()
   159→        })
   160→        .map(|s| s.to_string())
   161→        .collect()
   162→}
   163→
   164→/// Get the path to a crate directory
   165→fn get_crate_path(name: &str, workspace_root: &Path) -> std::path::PathBuf {
   166→    if name.starts_with("ex-") || name.starts_with("hw-") {
   167→        workspace_root.join("apps").join(name)
   168→    } else if name == "is-libc-used" {
   169→        workspace_root.join("tools").join(name)
   170→    } else {
   171→        workspace_root.join(name)
   172→    }
   173→}
   174→
   175→/// Check if a crate has a binary (src/main.rs)
   176→fn crate_has_binary(name: &str, workspace_root: &Path) -> bool {
   177→    get_crate_path(name, workspace_root)
   178→        .join("src/main.rs")
   179→        .exists()
   180→}
   181→
   182→/// Run a cargo command on a single crate
   183→fn run_cargo_on_crate(
   184→    cmd_name: &str,
   185→    crate_name: &str,
   186→    workspace_root: &Path,
   187→    config: &Config,
   188→) -> TestResult {
   189→    let is_musl = crate_name.contains("musl");
   190→    let is_x2 = crate_name.ends_with("-x2");
   191→    let use_optimized = config.optimized && is_x2;
   192→
   193→    let target_info = if is_musl {
   194→        " (musl)"
   195→    } else if use_optimized {
   196→        " (optimized)"
   197→    } else {
   198→        ""
   199→    };
   200→
   201→    println!("=== {crate_name}{target_info} ===");
   202→
   203→    let mut cmd = Command::new("cargo");
   204→
   205→    // Use nightly toolchain for optimized builds
   206→    if use_optimized {
   207→        cmd.arg("+nightly");
   208→    }
   209→
   210→    cmd.arg(cmd_name);
   211→
   212→    if !config.debug {
   213→        cmd.arg("--release");
   214→    }
   215→
   216→    cmd.args(["-p", crate_name]);
   217→
   218→    if is_musl {
   219→        cmd.args(["--target", "x86_64-unknown-linux-musl"]);
   220→    } else if use_optimized {
   221→        // Use custom target with build-std and panic-immediate-abort
   222→        cmd.args(["-Z", "build-std=std,core,panic_abort"]);
   223→        cmd.args(["-Z", "panic-immediate-abort"]);
   224→
   225→        // WORKAROUND: Generate a linker "version config" file to make all symbols
   226→        // LOCAL except _start. This allows --gc-sections to remove unreferenced
   227→        // functions, reducing stripped binary size of something like ex-x2:
   228→        //    use std::process::ExitCode;
   229→        //
   230→        //    // Force rlibc-x2 to be linked
   231→        //    extern crate rlibc_x2;
   232→        //
   233→        //    fn main() -> ExitCode {
   234→        //        ExitCode::from(42)
   235→        //    }
   236→        // From ~13KB -> ~6KB.
   237→        //
   238→        // This is frustratingly complex. When building an executable (not a shared
   239→        // library), there's no good reason for internal symbols to be GLOBAL/exported.
   240→        // The only entry point is _start - nothing external can call our internal
   241→        // functions at runtime.
   242→        //
   243→        // The linker should have a simple flag like "--executable-hide-symbols" that
   244→        // automatically makes all symbols local except the entry point. This would:
   245→        // 1. Enable dead code elimination via --gc-sections
   246→        // 2. Improve security by hiding internal implementation details
   247→        // 3. Reduce binary size by eliminating .dynsym bloat
   248→        // Instead, we must create a "version script" file with arcane syntax!
   249→        // Another short term solution would be to accept the configuration directly:
   250→        //   link-arg=-Wl,--version-script="{ global: _start; local:*; }"
   251→        let target_dir = workspace_root.join("target");
   252→        let _ = fs::create_dir_all(&target_dir);
   253→        let version_config = target_dir.join("rlibcx2-version.config");
   254→        if let Ok(mut f) = fs::File::create(&version_config) {
   255→            let _ = writeln!(f, "{{ global: _start; local: *; }};");
   256→        }
   257→
   258→        cmd.env(
   259→            "RUSTFLAGS",
   260→            format!(
   261→                "-C panic=immediate-abort -Z unstable-options -C link-arg=-Wl,--gc-sections -C link-arg=-Wl,--version-script={}",
   262→                version_config.display()
   263→            ),
   264→        );
   265→        let target_json = workspace_root.join("x86_64-unknown-linux-rlibcx2.json");
   266→        cmd.arg("--target");
   267→        cmd.arg(&target_json);
   268→    }
   269→
   270→    cmd.current_dir(workspace_root);
   271→
   272→    // Capture mtime before build for strip decision on run command
   273→    let binary_path = get_binary_path(crate_name, workspace_root, config);
   274→    let mtime_before = get_mtime(&binary_path);
   275→
   276→    if config.quiet {
   277→        cmd.stdout(Stdio::piped());
   278→        cmd.stderr(Stdio::piped());
   279→
   280→        match cmd.output() {
   281→            Ok(output) => {
   282→                let passed = output.status.success();
   283→                let exit_code = output.status.code().unwrap_or(-1);
   284→                let stderr = String::from_utf8_lossy(&output.stderr);
   285→
   286→                if cmd_name == "run" {
   287→                    println!("  exit code: {exit_code}");
   288→                    // Only strip if binary was rebuilt (mtime changed)
   289→                    let mtime_after = get_mtime(&binary_path);
   290→                    let was_rebuilt = mtime_after > mtime_before;
   291→                    if config.strip && was_rebuilt {
   292→                        strip_binary(crate_name, workspace_root, config);
   293→                    }
   294→                } else if passed {
   295→                    if cmd_name == "build" {
   296→                        println!("  {}", binary_path.display());
   297→                    }
   298→                    if config.strip {
   299→                        strip_binary(crate_name, workspace_root, config);
   300→                    }
   301→                }
   302→                if !passed && cmd_name != "run" {
   303→                    println!("  FAILED");
   304→                    eprintln!("{stderr}");
   305→                }
   306→
   307→                TestResult {
   308→                    name: crate_name.to_string(),
   309→                    passed,
   310→                    output: stderr.to_string(),
   311→                }
   312→            }
   313→            Err(e) => {
   314→                eprintln!("  Failed to run cargo {cmd_name}: {e}");
   315→                TestResult {
   316→                    name: crate_name.to_string(),
   317→                    passed: false,
   318→                    output: e.to_string(),
   319→                }
   320→            }
   321→        }
   322→    } else {
   323→        // Verbose mode - show all output
   324→        let status = cmd.status();
   325→        let (passed, exit_code) = match &status {
   326→            Ok(s) => (s.success(), s.code().unwrap_or(-1)),
   327→            Err(_) => (false, -1),
   328→        };
   329→
   330→        if cmd_name == "run" {
   331→            println!("  exit code: {exit_code}");
   332→            // Only strip if binary was rebuilt (mtime changed)
   333→            let mtime_after = get_mtime(&binary_path);
   334→            let was_rebuilt = mtime_after > mtime_before;
   335→            if config.strip && was_rebuilt {
   336→                strip_binary(crate_name, workspace_root, config);
   337→            }
   338→        } else if passed {
   339→            if cmd_name == "build" {
   340→                println!("  {}", binary_path.display());
   341→            }
   342→            if config.strip {
   343→                strip_binary(crate_name, workspace_root, config);
   344→            }
   345→        }
   346→        println!();
   347→
   348→        TestResult {
   349→            name: crate_name.to_string(),
   350→            passed,
   351→            output: String::new(),
   352→        }
   353→    }
   354→}
   355→
   356→/// Get the path to the built binary
   357→fn get_binary_path(crate_name: &str, workspace_root: &Path, config: &Config) -> std::path::PathBuf {
   358→    let profile = if config.debug { "debug" } else { "release" };
   359→    let target_subdir = if crate_name.contains("musl") {
   360→        "x86_64-unknown-linux-musl"
   361→    } else if config.optimized && crate_name.ends_with("-x2") {
   362→        "x86_64-unknown-linux-rlibcx2"
   363→    } else {
   364→        ""
   365→    };
   366→
   367→    if target_subdir.is_empty() {
   368→        workspace_root.join(format!("target/{profile}/{crate_name}"))
   369→    } else {
   370→        workspace_root.join(format!("target/{target_subdir}/{profile}/{crate_name}"))
   371→    }
   372→}
   373→
   374→/// Get the mtime of a file, if it exists
   375→fn get_mtime(path: &Path) -> Option<std::time::SystemTime> {
   376→    fs::metadata(path).ok().and_then(|m| m.modified().ok())
   377→}
   378→
   379→/// Strip debug symbols from the built binary
   380→fn strip_binary(crate_name: &str, workspace_root: &Path, config: &Config) {
   381→    let binary_path = get_binary_path(crate_name, workspace_root, config);
   382→
   383→    if binary_path.exists() {
   384→        let status = Command::new("strip").arg(&binary_path).status();
   385→        match status {
   386→            Ok(s) if s.success() => {
   387→                if !config.quiet {
   388→                    if let Ok(meta) = fs::metadata(&binary_path) {
   389→                        println!("  stripped: {} bytes", meta.len());
   390→                    }
   391→                }
   392→            }
   393→            _ => {
   394→                eprintln!("  warning: failed to strip {}", binary_path.display());
   395→            }
   396→        }
   397→    }
   398→}
   399→
   400→fn parse_args() -> Config {
   401→    let args: Vec<String> = std::env::args().skip(1).collect();
   402→    let mut args_iter = args.iter();
   403→
   404→    // Parse subcommand (first argument)
   405→    let subcommand = match args_iter.next().map(|s| s.as_str()) {
   406→        Some("build") => Subcommand::Build,
   407→        Some("run") => Subcommand::Run,
   408→        Some("test") => Subcommand::Test,
   409→        Some("-h" | "--help") => {
   410→            print_main_help();
   411→            std::process::exit(0);
   412→        }
   413→        Some(other) => {
   414→            eprintln!("Unknown command: {other}");
   415→            eprintln!("Use --help for usage information");
   416→            std::process::exit(1);
   417→        }
   418→        None => {
   419→            print_main_help();
   420→            std::process::exit(0);
   421→        }
   422→    };
   423→
   424→    let mut config = Config {
   425→        subcommand,
   426→        quiet: false,
   427→        fail_fast: false,
   428→        debug: true, // Default to debug for faster iteration; use -r for release
   429→        optimized: false,
   430→        strip: false,
   431→        crates: Vec::new(),
   432→    };
   433→
   434→    // Parse options and positional arguments for the subcommand
   435→    for arg in args_iter {
   436→        match arg.as_str() {
   437→            "-q" | "--quiet" => config.quiet = true,
   438→            "-f" | "--fail-fast" | "--fail" => config.fail_fast = true,
   439→            "-r" | "--release" => config.debug = false,
   440→            "-d" | "--debug" => config.debug = true,
   441→            "-opt" | "--optimized" => config.optimized = true,
   442→            "-s" | "--strip" => config.strip = true,
   443→            "-h" | "--help" => {
   444→                match config.subcommand {
   445→                    Subcommand::Build => print_cmd_help("build"),
   446→                    Subcommand::Run => print_cmd_help("run"),
   447→                    Subcommand::Test => print_test_help(),
   448→                }
   449→                std::process::exit(0);
   450→            }
   451→            other if other.starts_with('-') => {
   452→                eprintln!("Unknown option: {other}");
   453→                eprintln!("Use --help for usage information");
   454→                std::process::exit(1);
   455→            }
   456→            "." => {
   457→                match resolve_current_crate() {
   458→                    Ok(Some(name)) => config.crates.push(name),
   459→                    Ok(None) => {} // Workspace root - leave crates empty for "all"
   460→                    Err(e) => {
   461→                        eprintln!("{e}");
   462→                        std::process::exit(1);
   463→                    }
   464→                }
   465→            }
   466→            crate_name => {
   467→                config.crates.push(crate_name.to_string());
   468→            }
   469→        }
   470→    }
   471→
   472→    config
   473→}
   474→
   475→/// Resolve "." to the crate name in the current directory
   476→/// Returns None if at workspace root (meaning "all"), Some(name) for a crate, or error
   477→fn resolve_current_crate() -> Result<Option<String>, String> {
   478→    let cargo_toml = std::env::current_dir()
   479→        .map_err(|e| format!("Failed to get current directory: {e}"))?
   480→        .join("Cargo.toml");
   481→
   482→    if !cargo_toml.exists() {
   483→        return Err("No Cargo.toml found in current directory".to_string());
   484→    }
   485→
   486→    let content =
   487→        fs::read_to_string(&cargo_toml).map_err(|e| format!("Failed to read Cargo.toml: {e}"))?;
   488→
   489→    // Simple parsing - look for name = "..." in [package] section
   490→    let mut in_package = false;
   491→    for line in content.lines() {
   492→        let line = line.trim();
   493→        if line == "[package]" {
   494→            in_package = true;
   495→            continue;
   496→        }
   497→        if line.starts_with('[') {
   498→            in_package = false;
   499→            continue;
   500→        }
   501→        if in_package && line.starts_with("name") {
   502→            // Parse: name = "crate-name"
   503→            if let Some(eq_pos) = line.find('=') {
   504→                let value = line[eq_pos + 1..].trim();
   505→                let value = value.trim_matches('"').trim_matches('\'');
   506→                return Ok(Some(value.to_string()));
   507→            }
   508→        }
   509→    }
   510→
   511→    // No [package] section - likely workspace root, treat as "all"
   512→    Ok(None)
   513→}
   514→
   515→fn print_main_help() {
   516→    println!("Usage: cargo xtask <COMMAND> [OPTIONS]");
   517→    println!();
   518→    println!("Commands:");
   519→    println!("  build   Build crates");
   520→    println!("  run     Build and run crates");
   521→    println!("  test    Run tests");
   522→    println!();
   523→    println!("Options:");
   524→    println!("  -h, --help    Show this help");
   525→    println!();
   526→    println!("Run 'cargo xtask <COMMAND> --help' for command-specific options");
   527→}
   528→
   529→fn print_cmd_help(cmd: &str) {
   530→    println!("Usage: cargo xtask {cmd} [OPTIONS] [CRATES]...");
   531→    println!();
   532→    println!("Run 'cargo {cmd}' on crates. With no crates specified, {cmd}s all.");
   533→    println!();
   534→    println!("Arguments:");
   535→    println!("  [CRATES]...       Crates to {cmd} (e.g., ex-x1, hw-x2)");
   536→    println!("                    Use '.' for the crate in the current directory");
   537→    println!("                    Musl target auto-detected from crate name");
   538→    println!();
   539→    println!("Options:");
   540→    println!("  -q, --quiet       Suppress output (default is verbose)");
   541→    println!("  -f, --fail-fast   Stop on first failure");
   542→    println!("  -d, --debug       Use debug builds (default)");
   543→    println!("  -r, --release     Use release builds");
   544→    println!("  -opt, --optimized Use nightly optimizations for x2 crates (smaller binaries)");
   545→    println!("  -s, --strip       Strip debug symbols from binaries after building");
   546→    println!("  -h, --help        Show this help");
   547→    println!();
   548→    println!("Examples:");
   549→    println!("  cargo xtask {cmd}             # {cmd} all");
   550→    println!("  cargo xtask {cmd} .           # {cmd} crate in current directory");
   551→    println!("  cargo xtask {cmd} ex-x1       # {cmd} ex-x1 only");
   552→    println!("  cargo xtask {cmd} ex-x2 -opt  # {cmd} ex-x2 with nightly optimizations");
   553→}
   554→
   555→fn print_test_help() {
   556→    println!("Usage: cargo xtask test [OPTIONS] [CRATES]...");
   557→    println!();
   558→    println!("Run repository tests. With no crates specified, runs all tests.");
   559→    println!("With crates specified, tests only those crates.");
   560→    println!();
   561→    println!("Arguments:");
   562→    println!("  [CRATES]...       Crates to test (e.g., ex-x1, hw-x2, rlibc-x2)");
   563→    println!("                    Use '.' for the crate in the current directory");
   564→    println!("                    Musl target auto-detected from crate name");
   565→    println!("                    Specifying rlibc-x2 also runs rlibc-x2-tests");
   566→    println!();
   567→    println!("Options:");
   568→    println!("  -q, --quiet       Suppress output (default is verbose)");
   569→    println!("  -f, --fail-fast   Stop on first failure");
   570→    println!("  -d, --debug       Use debug builds (default)");
   571→    println!("  -r, --release     Use release builds");
