fn print_test_help() {
    println!("Usage: cargo xtask test [OPTIONS] [CRATES]...");
    println!();
    println!("Run repository tests. With no crates specified, runs all tests.");
    println!("With crates specified, tests only those crates.");
    println!();
    println!("Arguments:");
